76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    /**
92	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
93	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
94	     */
95	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
96	        List<String> missing = new ArrayList<>();
97	        if (isBlank(ownerFieldsDto.getFirstName())) {
98	            missing.add("firstName");
99	        }
100	        if (isBlank(ownerFieldsDto.getLastName())) {
101	            missing.add("lastName");
102	        }
103	        if (isBlank(ownerFieldsDto.getAddress())) {
104	            missing.add("address");
105	        }
106	        if (isBlank(ownerFieldsDto.getCity())) {
107	            missing.add("city");
108	        }
109	        if (isBlank(ownerFieldsDto.getTelephone())) {
110	            missing.add("telephone");
111	        }
112	        if (!missing.isEmpty()) {
113	            throw new RequiredFieldsMissingException(missing);
114	        }
115	    }
116	
117	    private static boolean isBlank(String value) {
118	        return value == null || value.isBlank();
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
124	        Owner owner = this.clinicService.findOwnerById(ownerId);
125	        if (owner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
129	    }
